          diag: [{ p: '내일 전화할 거예요', note: '“Because of what you said” = a reaction: 전화할게요.' }, { p: '내일 전화할께요', note: 'Written 게요: 전화할게요.' }, { p: '내일 전화하을게요', note: '하 ends in a vowel: 할게요.' }],
